-- Adds Boses Filipina to a Studio that was already seeded, or refreshes it. Safe to run again.
begin;
update public.studio_projects set position = position + 1
  where not exists (select 1 from public.studio_projects where slug = 'boses-filipina');
insert into public.studio_projects
  (slug, position, published, name, kind, category, tags, stamps, year, years, role_short, role, platform, status,
   live_url, docs_url, design_system_url, screenshots, facts, stats, entries)
values ($t$boses-filipina$t$, 0, true, $t$Boses Filipina$t$, $t$Voiceover portfolio with its own CMS$t$, $t$Creative portfolio · Web design & build$t$, array[$t$web$t$, $t$portfolio$t$, $t$brand$t$]::text[], array[$t$voice$t$, $t$creative$t$]::text[], 2026, $t$Jun 2025–Nov 2026$t$, $t$Designer & builder · pro bono$t$, $t$Product Designer & Builder (pro bono), solo, working directly with the client; rebuilt with Claude as an AI pair programmer$t$, $t$Web$t$, $t$live$t$, $t$https://www.lovelineloverez.com$t$, null, null, $j$[{"label":"Scrapbook homepage","src":"/projects/boses-filipina/home.webp"},{"label":"Cassette demo reels","src":"/projects/boses-filipina/demos.webp"},{"label":"Her Studio","src":"/projects/boses-filipina/studio.webp"}]$j$::jsonb, $j$[{"label":"Audio-first","value":"Agencies hear the work, get her specialization and contact her directly."},{"label":"Rebuilt as a scrapbook, November 2026","value":"Torn paper, washi tape and hand-drawn arrows, in the dark mode she prefers."},{"label":"Her own Studio","value":"She uploads demos and reels, edits her rate card and answers bookings without waiting for me."}]$j$::jsonb, $j$[{"value":"6","label":"pages, from demos to bookings"},{"value":"7","label":"Studio sections she edits herself"},{"value":"1 day","label":"from Figma Sites to code and a CMS"}]$j$::jsonb, $j$[{"stage":"overview","label":"Overview","date":"Dear diary, June 2025","body":"A voiceover artist asked me for a portfolio. I’m building her an audio-first home instead, where agencies and clients can hear her work, understand her specialization and reach her directly."},{"stage":"challenge","label":"Context & challenge","date":"June 2025","body":"Marketplaces like Fiverr and Voices.com take away control over presentation, branding and discovery. In a marketplace every artist looks roughly the same."},{"stage":"approach","label":"Approach","date":"Along the way","body":"Clients scan titles, play a few seconds and decide almost immediately. So featured demos sit above the fold, previews play right from the cards, and nothing stands between landing and listening. In November 2026 I rebuilt it in code as a scrapbook: demos as cassette tapes with their own players, reels on a film strip, and her rate card on graph paper."},{"stage":"outcome","label":"Outcome","date":"November 2026","body":"The first version shipped on Figma Sites in February 2026. The scrapbook rebuild went live in November with a Studio of her own, so new demos, reels and rates no longer wait for me, and bookings land straight in her Studio."},{"stage":"reflection","label":"Reflection","date":"Looking back","body":"[Your reflection on Boses Filipina goes here.]"}]$j$::jsonb)
on conflict (slug) do update set
  name = excluded.name, kind = excluded.kind, category = excluded.category, tags = excluded.tags, stamps = excluded.stamps,
  year = excluded.year, years = excluded.years, role_short = excluded.role_short, role = excluded.role, platform = excluded.platform,
  status = excluded.status, live_url = excluded.live_url, docs_url = excluded.docs_url, design_system_url = excluded.design_system_url,
  screenshots = excluded.screenshots, facts = excluded.facts, stats = excluded.stats, entries = excluded.entries;
commit;
